"""Figure for the indicator search -> reports/figures/bl_ind_logic.png"""
import sys, os, warnings; sys.path.insert(0, '.'); warnings.filterwarnings('ignore')
import numpy as np, pandas as pd, json, matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt
from bl_common import OUT
FIG = os.path.join(os.path.dirname(OUT), 'reports', 'figures'); os.makedirs(FIG, exist_ok=True)
F = pd.read_csv(f'{OUT}/bl_ind_family_cv.csv'); FN = pd.read_csv(f'{OUT}/bl_ind_fine.csv'); Z = pd.read_csv(f'{OUT}/bl_ind_zone.csv'); R2 = json.load(open(f'{OUT}/bl_summary_ind2.json'))
fig, ax = plt.subplots(2, 2, figsize=(13.5, 9.5))
a = ax[0, 0]; f = F.sort_values('A_crossvalidated'); cols = ['#d62728' if x == 'Donchian position' else ('#1f77b4' if x in ('EMA z', 'Bollinger z', 'CCI-like gap/MAD', 'gap/ATR') else '#7f7f7f') for x in f.family]; a.barh(range(len(f)), f.A_crossvalidated, color=cols); a.set_yticks(range(len(f))); a.set_yticklabels(f.family, fontsize=7); a.set_xlim(.5, .95); a.set_xlabel('activation AUC, parameter chosen on the other half of the cycles'); a.set_title('A. Which indicator separates pair seconds from random seconds?')
a = ax[0, 1]; a.plot(FN.N_min, FN.AUC, 'o-', color='#d62728'); a.fill_between(FN.N_min, FN.lo, FN.hi, color='#d62728', alpha=.15); a.axvspan(45, 65, color='k', alpha=.07); a.set_xlabel('channel length N (minutes)'); a.set_ylabel('activation AUC of |position in the N-minute range − 0.5|'); a.set_title('B. Channel length: a plateau at about 45–65 minutes')
a = ax[1, 0]; z = Z[Z.indicator == 'Donchian position|60']; a.bar(z.control_decile - .2, z.share_events * 100, .4, color='#ff7f0e', label='reactive pairs'); a.bar(z.control_decile + .2, z.share_controls * 100, .4, color='#7f7f7f', label='random seconds'); a.set_xticks(range(1, 11)); a.set_xlabel('decile of |position − 0.5| in the trailing 60-minute high–low range (10 = at / beyond the edge)'); a.set_ylabel('% of seconds'); a.set_title('C. 79% of pairs sit at the edge of the 60-minute range'); a.legend(fontsize=8)
a = ax[1, 1]; h = pd.DataFrame(R2['since']); lab = ['not in\nbreakout', '1st min', '2nd', '3rd', '4–5th', '6–10th']; a.bar(range(len(h)), h.per1000, color=['#7f7f7f'] + ['#d62728'] * (len(h) - 1)); a.set_xticks(range(len(h))); a.set_xticklabels(lab[:len(h)], fontsize=8); a.set_ylabel('reactive pairs per 1000 cycle-minutes'); a.set_xlabel('minutes since a completed bar closed beyond its previous 60 closes'); a.set_title('D. Completed-bar breakout: pairs come at once, but not every time')
for i, (e, n) in enumerate(zip(h['sum'], h['size'])): a.text(i, h.per1000.iloc[i] + 2, f'{int(e)}/{int(n)}', ha='center', fontsize=7)
fig.suptitle('Algo 8 reactive pairs: best-fitting indicator — in-sample, D-1, 363 pairs', fontsize=11); fig.tight_layout(); fig.savefig(f'{FIG}/bl_ind_logic.png', dpi=140); print('saved')
